#include "typed-field-line-parser.h"
#include <charconv>
#include <cctype>
#include <set>
namespace typed_fields {ParseError::ParseError(std::size_t o,const std::string& m):std::runtime_error(m),offset_(o){}std::size_t ParseError::offset()const noexcept{return offset_;}static bool start(char c){return std::isalpha(static_cast<unsigned char>(c))||c=='_';}static bool part(char c){return std::isalnum(static_cast<unsigned char>(c))||c=='_';}std::vector<Field> parse_line(std::string_view s){for(std::size_t k=0;k<s.size();++k)if(s[k]=='\0')throw ParseError(k,"NUL");std::size_t i=0;std::vector<Field> out;std::set<std::string> keys;auto ws=[&]{while(i<s.size()&&std::isspace(static_cast<unsigned char>(s[i])))++i;};ws();while(i<s.size()){auto key_at=i;if(!start(s[i]))throw ParseError(i,"key");++i;while(i<s.size()&&part(s[i]))++i;std::string key(s.substr(key_at,i-key_at));if(!keys.insert(key).second)throw ParseError(key_at,"duplicate");ws();if(i==s.size()||s[i]!='=')throw ParseError(i,"equals");++i;ws();Value value;if(i<s.size()&&s[i]=='"'){++i;std::string text;bool closed=false;while(i<s.size()){char c=s[i++];if(c=='"'){closed=true;break;}if(c=='\\'){if(i==s.size())throw ParseError(i-1,"escape");char e=s[i++];switch(e){case 'n':text+='\n';break;case 't':text+='\t';break;case '\\':text+='\\';break;case '"':text+='"';break;case ';':text+=';';break;default:throw ParseError(i-1,"escape");}}else text+=c;}if(!closed)throw ParseError(i,"quote");value=std::move(text);ws();}else{auto begin=i;while(i<s.size()&&s[i]!=';')++i;auto end=i;while(end>begin&&std::isspace(static_cast<unsigned char>(s[end-1])))--end;if(begin==end)throw ParseError(begin,"value");auto token=s.substr(begin,end-begin);if(token=="true")value=true;else if(token=="false")value=false;else{std::int64_t number=0;auto result=std::from_chars(token.data(),token.data()+token.size(),number);if(result.ec==std::errc{}&&result.ptr!=token.data())value=number;else if(result.ec==std::errc::result_out_of_range)throw ParseError(begin,"integer range");else value=std::string(token);}}out.push_back({std::move(key),std::move(value)});if(i==s.size())break;if(s[i]!=';')throw ParseError(i,"separator");++i;ws();if(i==s.size())throw ParseError(i,"field");}return out;}}
